// Ambient declaration for the build-time manifest injected via the
// `#pg-manifest` alias (generated by the module setup in `src/module.ts`).
declare module '#pg-manifest' {
  /**
   * The `pg` configuration metadata parsed at build time, or null when no
   * config file was found. String values may still contain `${VAR:default}`
   * placeholders, which the runtime resolves from the environment before use.
   */
  export const pgConfigMetadata: import('@opencowstudio/pg-core').PgConfigMetadata | null
}

declare module '#pg-entities-manifest' {
  /**
   * Formatted JSON string of the scanned entity collection, or an empty array
   * when no entities were found at build time. The runtime parses this back
   * into an array of `PgEntityMetadata` objects.
   */
  export const pgEntitiesJson: string
}
